// IdentityReadServiceServer is the server API for IdentityReadService service.
// All implementations must embed UnimplementedIdentityReadServiceServer
// for forward compatibility.
//
// IdentityReadService answers who a user is (roles and groups) for every
// internal service, and runs the self-service sign-in steps. Callers don't
// cache its answers across requests.
type IdentityReadServiceServer interface {
	// ResolveClaims looks a user up by the sign-in service's subject and
	// creates the account on first sight (just-in-time), unless the user's SSO
	// connection turned that off.
	ResolveClaims(context.Context, *ResolveClaimsRequest) (*ResolveClaimsResponse, error)
	// GetUser fetches one user by id. With a session_id it also records that
	// sign-in session as just used (see Session.last_seen_at).
	GetUser(context.Context, *GetUserRequest) (*GetUserResponse, error)
	// GetUserByEmail finds one user by exact, case-insensitive email, across
	// local and SSO accounts. It never creates one; NotFound when none matches.
	GetUserByEmail(context.Context, *GetUserByEmailRequest) (*GetUserByEmailResponse, error)
	// JitProvisionByEmail finds a user by email like GetUserByEmail, and
	// creates an SSO account when none exists. The gateway calls it on an SSO
	// callback; any error must abort the sign-in.
	JitProvisionByEmail(context.Context, *JitProvisionByEmailRequest) (*JitProvisionByEmailResponse, error)
	// ListUsersInGroup lists a group's users, optionally with its descendants'.
	ListUsersInGroup(context.Context, *ListUsersInGroupRequest) (*ListUsersInGroupResponse, error)
	// GetGroup fetches one group by id.
	GetGroup(context.Context, *GetGroupRequest) (*GetGroupResponse, error)
	// ListGroupDescendants lists every descendant of a group, in topological
	// order.
	ListGroupDescendants(context.Context, *ListGroupDescendantsRequest) (*ListGroupDescendantsResponse, error)
	// ListGroupAncestors lists a group's ancestors, the root last.
	ListGroupAncestors(context.Context, *ListGroupAncestorsRequest) (*ListGroupAncestorsResponse, error)
	// ResolveEmail returns a user's email by id.
	ResolveEmail(context.Context, *ResolveEmailRequest) (*ResolveEmailResponse, error)
	// ResolveFCMToken returns a user's push notification token by id.
	ResolveFCMToken(context.Context, *ResolveFCMTokenRequest) (*ResolveFCMTokenResponse, error)
	// ListUserGroups lists the groups a user is a direct member of, optionally
	// with every descendant of them.
	ListUserGroups(context.Context, *ListUserGroupsRequest) (*ListUserGroupsResponse, error)
	// ListUsersByEmail searches emails by case-insensitive substring, sorted by
	// email then id, a page at a time. Deleted accounts are left out unless
	// include_deleted is set.
	ListUsersByEmail(context.Context, *ListUsersByEmailRequest) (*ListUsersByEmailResponse, error)
	// ListGroups lists the groups under parent_id (empty for the roots),
	// optionally with all their descendants, sorted by name, a page at a time.
	ListGroups(context.Context, *ListGroupsRequest) (*ListGroupsResponse, error)
	// ListUsersByIdpGroups lists the users holding any of the named identity
	// provider groups.
	ListUsersByIdpGroups(context.Context, *ListUsersByIdpGroupsRequest) (*ListUsersByIdpGroupsResponse, error)
	// CountUsersByIdpGroups counts the users holding any of the named identity
	// provider groups.
	CountUsersByIdpGroups(context.Context, *CountUsersByIdpGroupsRequest) (*CountUsersByIdpGroupsResponse, error)
	// ListAllUsers lists every enabled user: the audience of "Everyone".
	ListAllUsers(context.Context, *ListAllUsersRequest) (*ListAllUsersResponse, error)
	// CountAllUsers counts every enabled user.
	CountAllUsers(context.Context, *CountAllUsersRequest) (*CountAllUsersResponse, error)
	// ListUserIdpGroups returns one user's identity provider group names.
	ListUserIdpGroups(context.Context, *ListUserIdpGroupsRequest) (*ListUserIdpGroupsResponse, error)
	// RevokeMySessions revokes every session of the calling user.
	RevokeMySessions(context.Context, *RevokeMySessionsRequest) (*RevokeMySessionsResponse, error)
	// GetSetupState reports whether first-run setup is still needed (no root
	// admin exists).
	GetSetupState(context.Context, *GetSetupStateRequest) (*GetSetupStateResponse, error)
	// BootstrapRoot creates the first root admin with a local password. It
	// succeeds, doing nothing, once a root admin exists.
	BootstrapRoot(context.Context, *BootstrapRootRequest) (*BootstrapRootResponse, error)
	// GetAuthConfig returns the non-secret sign-in settings the UI needs before
	// sign-in.
	GetAuthConfig(context.Context, *GetAuthConfigRequest) (*GetAuthConfigResponse, error)
	// RequestPasswordReset emails a password reset code to a local account.
	// The answer is the same whether or not the account exists.
	RequestPasswordReset(context.Context, *RequestPasswordResetRequest) (*RequestPasswordResetResponse, error)
	// ResetPasswordWithCode checks a password reset code and sets the new
	// password in the sign-in service.
	ResetPasswordWithCode(context.Context, *ResetPasswordWithCodeRequest) (*ResetPasswordWithCodeResponse, error)
	// RequestLoginOtp emails a sign-in code to a local account whose password
	// the UI already checked. The answer is the same whether or not the
	// account exists.
	RequestLoginOtp(context.Context, *RequestLoginOtpRequest) (*RequestLoginOtpResponse, error)
	// VerifyLoginOtp checks a sign-in code. It doesn't touch the session.
	VerifyLoginOtp(context.Context, *VerifyLoginOtpRequest) (*VerifyLoginOtpResponse, error)
	// MarkEmailVerified records that a user proved control of an address. The
	// caller has already checked the signed link that carries both values.
	// Repeating it succeeds with already_verified set. An address that no
	// longer matches the account is refused.
	MarkEmailVerified(context.Context, *MarkEmailVerifiedRequest) (*MarkEmailVerifiedResponse, error)
	// EnrollTotpBegin creates a pending authenticator secret and returns its
	// otpauth URI. Calling it again replaces a pending secret; a confirmed one
	// must be removed first.
	EnrollTotpBegin(context.Context, *EnrollTotpBeginRequest) (*EnrollTotpBeginResponse, error)
	// EnrollTotpConfirm checks a first code against the pending secret and
	// activates it.
	EnrollTotpConfirm(context.Context, *EnrollTotpConfirmRequest) (*EnrollTotpConfirmResponse, error)
	// VerifyTotp checks a code against the confirmed secret, one period either
	// way. ok is false for a wrong code and for no enrolment alike.
	VerifyTotp(context.Context, *VerifyTotpRequest) (*VerifyTotpResponse, error)
	// SendEmailOtp emails a single-use code for a purpose, valid for five
	// minutes. ResourceExhausted inside the cooldown.
	SendEmailOtp(context.Context, *SendEmailOtpRequest) (*SendEmailOtpResponse, error)
	// VerifyEmailOtp checks an emailed code for a purpose. ok is false for
	// wrong, expired, used and locked out alike.
	VerifyEmailOtp(context.Context, *VerifyEmailOtpRequest) (*VerifyEmailOtpResponse, error)
	// ListUserFactors lists the factor kinds the user can satisfy now.
	ListUserFactors(context.Context, *ListUserFactorsRequest) (*ListUserFactorsResponse, error)
	// RemoveFactor removes the user's factor of a kind: "totp", or "passkey"
	// for every passkey. The email factor can't be removed.
	RemoveFactor(context.Context, *RemoveFactorRequest) (*RemoveFactorResponse, error)
	// WebauthnRegisterBegin starts registering a passkey. The options are the
	// W3C creation options as JSON; existing credentials are excluded.
	WebauthnRegisterBegin(context.Context, *WebauthnRegisterBeginRequest) (*WebauthnRegisterBeginResponse, error)
	// WebauthnRegisterFinish checks the authenticator's answer and stores the
	// credential's public key. The session is used up either way.
	WebauthnRegisterFinish(context.Context, *WebauthnRegisterFinishRequest) (*WebauthnRegisterFinishResponse, error)
	// WebauthnAssertBegin starts a passkey sign-in over the user's credentials.
	// FailedPrecondition when the user has none.
	WebauthnAssertBegin(context.Context, *WebauthnAssertBeginRequest) (*WebauthnAssertBeginResponse, error)
	// WebauthnAssertFinish checks the assertion. ok is false for a failed check
	// and for a sign count that went backwards (a possible cloned key) alike.
	WebauthnAssertFinish(context.Context, *WebauthnAssertFinishRequest) (*WebauthnAssertFinishResponse, error)
	// ListWebauthnCredentials lists the user's passkeys.
	ListWebauthnCredentials(context.Context, *ListWebauthnCredentialsRequest) (*ListWebauthnCredentialsResponse, error)
	// RemoveWebauthnCredential removes one passkey.
	RemoveWebauthnCredential(context.Context, *RemoveWebauthnCredentialRequest) (*RemoveWebauthnCredentialResponse, error)
	// RenameMFAMethod labels one factor: method_id "totp" or a passkey's
	// credential id. An empty label clears it. The email factor can't be
	// labelled.
	RenameMFAMethod(context.Context, *RenameMFAMethodRequest) (*RenameMFAMethodResponse, error)
	// Discover routes an identifier (an email, or a username that is an
	// email's local part) to its domain's one sign-in method.
	Discover(context.Context, *DiscoverRequest) (*DiscoverResponse, error)
	// CheckBreakGlassEligibility reports whether an account may break glass:
	// root or site-admin, with a local credential.
	CheckBreakGlassEligibility(context.Context, *CheckBreakGlassEligibilityRequest) (*CheckBreakGlassEligibilityResponse, error)
	mustEmbedUnimplementedIdentityReadServiceServer()
}

